import sys
from functools import lru_cache

data = sys.stdin.read().split()
n = int(data[0])
types = data[1:1 + n]
mem = [int(x) for x in data[1 + n:1 + 2 * n]]
M = int(data[1 + 2 * n])
groups = {}
for t, m in zip(types, mem):
    groups.setdefault(t, []).append(m)

def solve(g):
    k = len(g)
    full = (1 << k) - 1

    @lru_cache(maxsize=None)
    def f(mask):
        if mask == 0:
            return 0
        i = 0
        while not (mask >> i) & 1:
            i += 1
        rest = mask & ~(1 << i)
        best = 1 + f(rest)
        for j in range(i + 1, k):
            if (rest >> j) & 1 and g[i] + g[j] <= M:
                best = min(best, 1 + f(rest & ~(1 << j)))
        return best

    return f(full)

print(sum(solve(g) for g in groups.values()))

